import { ActionDefinition } from '../../../Action'
import {
    ConditionsColumn,
    TableNameColumn,
    ChoiceColumn,
    FieldNameColumn,
    IntegerColumn,
    RecordsColumn,
} from '../../../../db'

export const lookUpRecords = ActionDefinition({
    $id: '43400a1587003300663ca1bb36cb0b4b',
    name: 'Look Up Records',
    description:
        'Look up multiple records on any ServiceNow table. You can configure the conditions for the records found. The output includes a list of records and the number of records found. Note: The maximum number of records that can be returned is configured by a property and by default is 10K records. If more than 10K records are found, only the first 10K are returned.',
    inputs: {
        conditions: ConditionsColumn({
            label: 'Conditions',
        }),
        table: TableNameColumn({
            label: 'Table',
        }),
        sort_type: ChoiceColumn({
            label: 'Sort Type',
            maxLength: 32,
            default: 'sort_asc',
            choices: {
                sort_asc: {
                    label: 'a to z',
                    sequence: 1,
                },
                sort_desc: {
                    label: 'z to a',
                    sequence: 2,
                },
            },
        }),
        sort_column: FieldNameColumn({
            label: 'Order by',
        }),
        max_results: IntegerColumn({
            label: 'Max Results',
            default: 1000,
        }),
    },
    outputs: {
        Table: TableNameColumn({
            label: 'Table',
        }),
        Count: IntegerColumn({
            label: 'Count',
        }),
        Records: RecordsColumn({
            label: 'Records',
            referenceTable: 'table',
            dependent: 'table',
        }),
    },
})
